#include <cstdarg>
#include <new>
#include <sys/stat.h>
#include <arm_neon.h>

/*
 * How it works
 *   A lowest-priority worker thread produces a small blurred strip of whatever is
 *   behind the overlay frame and publishes it; the renderer (drawGlassBackdrop in
 *   tesla.hpp) crossfades, upscales and tints it.
 *
 *   Sources:
 *   - Live (namespace live): the game's swapchain is read directly through the
 *     debug SVCs, as soon as the game finishes a frame. The slots are found by
 *     size in the game's address space, or by searching for a captured picture
 *     (discover()) and remembered per process. At HOME and in system applets
 *     the same reader follows vi's shared buffer instead (attachUi()).
 *   - Display controller (namespace dc): when nx-ovlloader maps its registers, they
 *     say which slot is on screen and how much of it the picture uses. The live
 *     reader then takes exactly that frame, and a capture check is only needed when
 *     the display shows something else.
 *   - Capture service (caps:sc): a JPEG of the screen with our layer excluded,
 *     decoded at 1/8 scale (DC-only decoder). Used for whatever can't be read
 *     (Album, hbmenu, unsupported games), and to verify that the live frame is
 *     really what is on screen whenever it stops changing.
 *
 *   Runs only while the overlay is visible and glass is on. If captures are
 *   blocked and the game isn't drawing, the normal background is shown instead.
 *   All memory is reserved in one go (reserve()) and kept; only release() frees it
 *   (6 MB, glass off, to make room for a wallpaper).
 */

// Diagnostics (live_logging.log) are only built with -DUSING_LIVE_LOGGING_DIRECTIVE=1.
// Otherwise GLASS_LOG expands to nothing (its arguments included) and everything else
// used only for logging sits inside #if USING_LIVE_LOGGING_DIRECTIVE.
#if USING_LIVE_LOGGING_DIRECTIVE
#define GLASS_LOG(...) ::ult::glass::live::log(__VA_ARGS__)
#else
#define GLASS_LOG(...) ((void)0)
#endif

